      "code": "# Q9: Fill missing values in columns 'A' and 'B' with 0\nimport pandas as pd\ndf = pd.DataFrame({'A': [1, None, 3], 'B': [None, 4, 5]})\nprint(\"Before:\\n\", df)\ndf[['A', 'B']] = df[['A', 'B']].fillna(0)\nprint(\"\\nAfter filling with 0:\\n\", df)",
      "codeHtml": "<span class=\"line\"><span class=\"tok-com\"># Q9: Fill missing values in columns &#x27;A&#x27; and &#x27;B&#x27; with 0</span></span><span class=\"line\"><span class=\"tok-kw\">import</span> pandas <span class=\"tok-kw\">as</span> pd</span><span class=\"line\">df = pd.<span class=\"tok-fn\">DataFrame</span>({&#x27;A&#x27;: [<span class=\"tok-num\">1</span>, <span class=\"tok-kw\">None</span>, <span class=\"tok-num\">3</span>], &#x27;B&#x27;: [<span class=\"tok-kw\">None</span>, <span class=\"tok-num\">4</span>, <span class=\"tok-num\">5</span>]})</span><span class=\"line\"><span class=\"tok-fn\">print</span>(&quot;Before:\\n&quot;, df)</span><span class=\"line\">df[[&#x27;A&#x27;, &#x27;B&#x27;]] = df[[&#x27;A&#x27;, &#x27;B&#x27;]].<span class=\"tok-fn\">fillna</span>(<span class=\"tok-num\">0</span>)</span><span class=\"line\"><span class=\"tok-fn\">print</span>(&quot;\\nAfter filling <span class=\"tok-kw\">with</span> <span class=\"tok-num\">0</span>:\\n&quot;, df)</span>",
      "outputLabel": "Output",
