      "code": "# Q13: Bar graph - employee id vs salary for two departments\nimport matplotlib.pyplot as plt\nimport numpy as np\neid = np.array([1, 2, 3, 4])\nsales_dept = [40000, 42000, 39000, 45000]\nit_dept = [55000, 58000, 52000, 60000]\nx = np.arange(len(eid)); width = 0.35\nplt.bar(x - width/2, sales_dept, width, label=\"Sales Dept\", color=\"navy\")\nplt.bar(x + width/2, it_dept, width, label=\"IT Dept\", color=\"goldenrod\")\nplt.xticks(x, eid); plt.xlabel(\"Employee ID\"); plt.ylabel(\"Salary\")\nplt.title(\"Salary Comparison - Two Departments\"); plt.legend()\nplt.savefig(\"q13_output.png\", dpi=120, bbox_inches=\"tight\")\nprint(\"Grouped bar chart saved as q13_output.png\")",
